/* "Shardwild cleared: X%" bar (Sprites). Generated by clearbar.py (export_js.py). NOT wired in yet.
 *
 * All pieces are RAW rows+palette with their own outline baked in: paint them 1:1 (like keyArt's mkRaw / the tile painters).
 * Do NOT run them through mkSprite (its extra outline + 1px pad would break the seams). '.' = transparent.
 * Every bar piece is 12 rows tall: the frame body is rows 1-10 (10px); the crystal caps poke 1px above and below.
 *
 * ASSEMBLE at any width W (W >= 32, game px):
 *   x=0:            leftCap (8 wide)
 *   x=8 .. W-9:     midFrame tiled (4 wide; use column (x-8)%4)  -> inner trough width inner=W-16
 *   x=W-8:          rightCap (8 wide)
 *   fill:           n=round(inner*frac); for i<n paint fill column i%4 into rows fillRow..fillRow+3 (fillRow=4) at x=8+i
 *   fill end cap:   if 2<=n<inner, paint fillCap (2 wide) at x=8+n-2, rows 4..7 (leading-edge highlight)
 *   notches:        for s=1..7, x=8+round(inner*s/8): paint the 1px 'notch' column (skip '.'); on rows 4..7 use 'P'
 *                   instead of 'k' where x < 8+n-2 (the notch shows as a dark seam in the energy).
 *   crown:          crownOff below 100%, crownOn at 100% (frac>=1). 9x7, drawn at (W+2, 3) i.e. right of the bar.
 *   frac = kills/8 (12.5% steps). Text "Shardwild cleared: X%" is drawn by the game font (suggest just under/over the bar).
 * Suggested on phone: W=120 game px, centred at the top (y~6). CLEAR_BAR.build(W,frac) returns rows for the whole bar
 * (without crown), CLEAR_BAR.toCanvas(W,frac) returns a canvas (cache it per kill count; it only changes 8 times).
 */
const CLEAR_BAR={"pal":{"k":"#0d0b12","f":"#5a4a70","F":"#30263e","B":"#1e1628","d":"#120e18","n":"#7a6898","c":"#8a3ad0","C":"#ff4fa8","W":"#ffd6ec","P":"#a01860","r":"#ff4fa8","R":"#ff9ccc","w":"#fff0f8","g":"#4a4652","G":"#7a7684","y":"#ffd34a","o":"#b8801c","Y":"#fff3b0"},"h":12,"capW":8,"fillRow":4,"leftCap":["....kW..","...kWCkk","..kWCCkf",".kWCCCkF","kWCCCWkk","kCCCCWkk","kccccckk","kPcccckk",".kPccckF","..kPcckB","...kPckk","....kP.."],"rightCap":["..Wk....","kkCWk...","fkCCWk..","FkCCCWk.","kkWCCCWk","kkWCCCCk","kkccccck","kkccccPk","FkcccPk.","BkccPk..","kkcPk...","..Pk...."],"midFrame":["....","kkkk","fffn","FFFF","dddd","dddd","dddd","dddd","FFFF","BBBB","kkkk","...."],"fill":["RRRR","rrrr","rrrr","PPPP"],"fillCap":["Rw","rw","rw","Pr"],"notch":[".",".","n",".","k",".",".","k",".","n",".","."],"crownOff":[".k..k..k.","kGkkGkkGk","kGGGGGGGk","kgggggggk","kgggggggk","kgggggggk","kkkkkkkkk"],"crownOn":[".k..k..k.","kYkkYkkYk","kyYyyyYyk","kyyyyyyyk","kyoyCyoyk","koooooook","kkkkkkkkk"]};
CLEAR_BAR.build=function(W,frac){
  const B=CLEAR_BAR,C=B.capW,inner=W-2*C,rows=[];
  for(let y=0;y<B.h;y++){let r=B.leftCap[y];for(let i=0;i<inner;i++)r+=B.midFrame[y][i%4];rows.push((r+B.rightCap[y]).split(''));}
  const n=Math.round(inner*Math.max(0,Math.min(1,frac)));
  for(let i=0;i<n;i++)for(let j=0;j<4;j++)rows[B.fillRow+j][C+i]=B.fill[j][i%4];
  if(n>=2&&n<inner)for(let j=0;j<4;j++)for(let k=0;k<2;k++)rows[B.fillRow+j][C+n-2+k]=B.fillCap[j][k];
  for(let s=1;s<8;s++){const x=C+Math.round(inner*s/8);
    for(let y=0;y<B.h;y++){let ch=B.notch[y];if(ch==='.')continue;if(y>=4&&y<=7&&x<C+n-2&&ch==='k')ch='P';rows[y][x]=ch;}}
  return rows.map(r=>r.join(''));
};
CLEAR_BAR.toCanvas=function(W,frac){
  const B=CLEAR_BAR,rows=B.build(W,frac),cr=frac>=1?B.crownOn:B.crownOff;
  const c=document.createElement('canvas');c.width=W+2+cr[0].length;c.height=B.h;const g=c.getContext('2d');
  const put=(rs,x0,y0)=>{for(let y=0;y<rs.length;y++)for(let x=0;x<rs[y].length;x++){const ch=rs[y][x];if(ch!=='.'){g.fillStyle=B.pal[ch];g.fillRect(x0+x,y0+y,1,1);}}};
  put(rows,0,0);put(cr,W+2,3);return c;
};
if(typeof module!=='undefined')module.exports={CLEAR_BAR};
